export const sleepTracks=[{id:'rain',name:'窗外细雨',icon:'☂'},{id:'stream',name:'林间溪流',icon:'≈'},{id:'insects',name:'夏夜虫鸣',icon:'☾'},{id:'sea',name:'轻柔海浪',icon:'〜'}];
export function createSleepSound({onWake=()=>{}}={}){
 const popup=document.createElement('dialog');popup.id='sleep-sound';popup.setAttribute('aria-labelledby','sleep-sound-title');
 popup.innerHTML='<header><h2 id="sleep-sound-title">听助眠</h2><button type="button" data-sleep-close aria-label="收起">×</button></header><section data-sleep-picker><div class="sleep-wheel-shell"><div class="sleep-wheel-band" aria-hidden="true"></div><div class="sleep-wheel" tabindex="0" role="listbox" aria-label="助眠声音" aria-activedescendant="sleep-option-rain">'+sleepTracks.map(t=>'<div role="option" id="sleep-option-'+t.id+'" data-sleep-track="'+t.id+'" aria-selected="false">'+t.name+'</div>').join('')+'</div></div><footer><button type="button" data-sleep-timer aria-label="定时关闭：30分钟">30 分钟</button><span role="status"></span></footer></section><section data-sleep-menu hidden><button type="button" data-sleep-wake>起床</button><button type="button" data-sleep-reselect>重选声音</button><button type="button" data-sleep-off>关闭声音</button></section>';
 document.body.append(popup);let ctx=null,selected=null,sleeping=false,minutes=30,deadline=0,serial=0,scrollTimer,armed=false;const nodes=new Map(),wheel=popup.querySelector('.sleep-wheel');let cursor=0;
 function node(id){if(nodes.has(id))return nodes.get(id);const audio=new Audio(new URL('./assets/sleep/'+(id==='rain'?'rain-light-248282':id)+'.mp3',import.meta.url));audio.loop=true;audio.preload='none';const gain=ctx.createGain();gain.gain.value=0;ctx.createMediaElementSource(audio).connect(gain).connect(ctx.destination);const n={audio,gain,id,version:0};nodes.set(id,n);audio.addEventListener('error',()=>{if(selected===n){stop();popup.querySelector('[role=status]').textContent='暂时播不了，换一种试试'}});return n}
 function fade(n,value,seconds){const p=n.gain.gain,t=ctx.currentTime;if(p.cancelAndHoldAtTime)p.cancelAndHoldAtTime(t);else{p.cancelScheduledValues(t);p.setValueAtTime(p.value,t)}p.linearRampToValueAtTime(value,t+seconds)}
 function retire(n){const version=++n.version;fade(n,0,1.2);setTimeout(()=>{if(n.version===version)n.audio.pause()},1250)}
 function paint(){popup.querySelectorAll('[data-sleep-track]').forEach(b=>b.setAttribute('aria-selected',String(selected?.id===b.dataset.sleepTrack)));popup.querySelector('[data-sleep-timer]').textContent=minutes?minutes+' 分钟':'不定时';popup.querySelector('[data-sleep-timer]').setAttribute('aria-label','定时关闭：'+(minutes?minutes+'分钟':'不定时'));popup.querySelector('[data-sleep-off]').disabled=!selected}
 function stop(){serial++;deadline=0;selected=null;nodes.forEach(retire);paint()}
 async function select(id){if(selected?.id===id)return;ctx??=new AudioContext();const resume=ctx.resume(),n=node(id),token=++serial;selected=n;n.version++;nodes.forEach(other=>{if(other!==n)retire(other)});deadline=minutes?Date.now()+minutes*60000:0;popup.querySelector('[role=status]').textContent='';paint();try{const playing=n.audio.play();await Promise.all([resume,playing]);if(token!==serial)return;window.dispatchEvent(new Event('echoo-sleep-play'));fade(n,id==='rain'?.20:.35,2)}catch{if(token!==serial)return;stop();popup.querySelector('[role=status]').textContent='再点一下试试'}}
 function hide(){armed=false;clearTimeout(scrollTimer);if(popup.open)popup.close()}
 function settle(){if(!armed||!popup.open)return;armed=false;cursor=Math.max(0,Math.min(3,Math.round(wheel.scrollTop/48)));wheel.scrollTo({top:cursor*48,behavior:'smooth'});wheel.setAttribute('aria-activedescendant','sleep-option-'+sleepTracks[cursor].id);select(sleepTracks[cursor].id)}
 function unlock(){ctx??=new AudioContext();ctx.resume().catch(()=>{});armed=true}
 wheel.addEventListener('pointerdown',unlock);wheel.addEventListener('wheel',unlock,{passive:true});
 wheel.addEventListener('scroll',()=>{clearTimeout(scrollTimer);if(armed)scrollTimer=setTimeout(settle,180)});
 wheel.addEventListener('pointerup',()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(settle,200)});
 wheel.addEventListener('click',e=>{const option=e.target.closest('[data-sleep-track]');if(!option)return;unlock();cursor=sleepTracks.findIndex(t=>t.id===option.dataset.sleepTrack);wheel.scrollTo({top:cursor*48,behavior:'smooth'});clearTimeout(scrollTimer);scrollTimer=setTimeout(settle,350)});
 wheel.addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','Home','End','Enter',' '].includes(e.key))return;e.preventDefault();unlock();cursor=e.key==='Home'?0:e.key==='End'?3:Math.max(0,Math.min(3,cursor+(e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0)));wheel.scrollTop=cursor*48;settle()});
 function picker(){popup.querySelector('[data-sleep-picker]').hidden=false;popup.querySelector('[data-sleep-menu]').hidden=true;popup.querySelector('h2').textContent='听助眠';if(!popup.open)popup.show();armed=false;cursor=selected?sleepTracks.findIndex(t=>t.id===selected.id):cursor;wheel.scrollTop=cursor*48;wheel.setAttribute('aria-activedescendant','sleep-option-'+sleepTracks[cursor].id)}
 popup.querySelector('[data-sleep-close]').onclick=hide;popup.addEventListener('cancel',()=>{armed=false;clearTimeout(scrollTimer)});
 popup.querySelector('[data-sleep-wake]').onclick=()=>onWake();popup.querySelector('[data-sleep-reselect]').onclick=picker;popup.querySelector('[data-sleep-off]').onclick=()=>{stop();hide()};
 popup.querySelector('[data-sleep-timer]').onclick=()=>{const values=[30,60,0,15];minutes=values[(values.indexOf(minutes)+1)%values.length];deadline=selected&&minutes?Date.now()+minutes*60000:0;paint()};
 function checkTimer(){if(deadline&&Date.now()>=deadline){stop();hide()}}
 setInterval(checkTimer,1000);document.addEventListener('visibilitychange',checkTimer);window.addEventListener('echoo-music-play',()=>{stop()});
 return {open({silent=false}={}){sleeping=true;stop();if(silent)hide();else picker()},reopen(){if(!sleeping)return;armed=false;clearTimeout(scrollTimer);popup.querySelector('[data-sleep-picker]').hidden=true;popup.querySelector('[data-sleep-menu]').hidden=false;popup.querySelector('h2').textContent='睡个好觉';paint();if(!popup.open)popup.show()},end(){sleeping=false;stop();hide()},state:()=>({selected:selected?.id||null,sleeping,open:popup.open,minutes,deadline})};
}
